'use strict';
const assert=require('node:assert/strict'),{create}=require('../demo-core');let groups=0;
const check=(name,fn)=>{fn();groups++;console.log('PASS '+name);};
const paid=(options={})=>{const c=create({now:()=>Date.parse('2026-10-26T00:00:00Z'),...options});c.setRequirement(3.5,6,true);c.requestPhone();c.resolvePhone('success');c.select(['SIM_BJ01_U03']);c.setDate('2026-10-26');c.quote();const o=c.submit();c.pay(o.id,'success');return {c,id:o.id};};
check('renewal has no default but retains the actively quoted six-month choice',()=>{const {c,id}=paid();assert.equal(c.orderDetail(id).service.renewalDraft,undefined);const q=c.renewalQuote(id,6);assert.equal(c.orderDetail(id).service.renewalDraft,'6');assert.equal(q.previous_end_date,'2027-04-26');assert.equal(q.new_end_date,'2027-10-26');});
check('six to twelve invalidates the quote immediately and blocks payment until re-priced',()=>{const {c,id}=paid();c.renewalQuote(id,6);c.setRenewalMonths(id,'12');assert.equal(c.orderDetail(id).service.renewalQuote,undefined);assert.throws(()=>c.payRenewal(id,12),/QUOTE_STALE/);assert.equal(c.orderDetail(id).service.renewals.length,0);const q=c.renewalQuote(id,12);assert.equal(q.rent_total,3120);assert.equal(q.coupon_discount,150);assert.equal(q.payable,2970);const p=c.payRenewal(id,12);assert.equal(p.months,12);assert.equal(c.rentalPeriod(id).total_months,18);assert.equal(c.rentalPeriod(id).end_date,'2028-04-26');});
check('payment rejects a changed visible month even without an input event',()=>{const {c,id}=paid();c.renewalQuote(id,6);assert.throws(()=>c.payRenewal(id,12),/QUOTE_STALE/);assert.equal(c.orderDetail(id).service.renewals.length,0);assert.equal(c.orderDetail(id).service.renewalQuote,undefined);});
check('clearing or entering an invalid renewal month cannot preserve a payable quote',()=>{for(const value of ['',0,1.5,61]){const {c,id}=paid();c.renewalQuote(id,6);c.setRenewalMonths(id,value);assert.equal(c.orderDetail(id).service.renewalQuote,undefined);assert.throws(()=>c.payRenewal(id),/QUOTE_STALE/);}});
check('expired and tampered renewal prices fail before recording a payment',()=>{let now=Date.parse('2026-10-26T00:00:00Z');const {c,id}=paid({now:()=>now});c.renewalQuote(id,6);now+=300001;assert.throws(()=>c.payRenewal(id,6),/QUOTE_STALE/);const next=paid();next.c.renewalQuote(next.id,6);const s=next.c.state();s.services[next.id].renewalQuote.payable=1;const d=create({state:s,now:()=>Date.parse('2026-10-26')});assert.throws(()=>d.payRenewal(next.id,6),/QUOTE_STALE/);assert.equal(d.orderDetail(next.id).service.renewals.length,0);});
check('paid renewal cannot repeat and the displayed end follows paid periods',()=>{const {c,id}=paid();c.renewalQuote(id,12);const p=c.payRenewal(id,12);assert.equal(p.new_end_date,c.rentalPeriod(id).end_date);assert.throws(()=>c.payRenewal(id,12),/QUOTE_STALE/);assert.equal(c.orderDetail(id).service.renewals.length,1);});
check('anniversary projection clamps month ends and supports leap years',()=>{for(const [start,end] of [['2027-01-31','2027-02-28'],['2028-01-31','2028-02-29']]){const {c,id}=paid();const s=c.state();s.orders[0].start_date=start;s.orders[0].term_months=1;const d=create({state:s,now:()=>Date.parse('2026-10-26')});assert.equal(d.rentalPeriod(id).end_date,end);assert.equal(d.renewalQuote(id,1).new_end_date,start.slice(0,4)+'-03-31');}});
check('supplementing enterprise data preserves identity and avoids duplicate lead records',()=>{let now=1;const c=create({now:()=>now});const lead=c.saveEnterpriseLead({phone:'13800000000',company:'首次',capacity_m3:3.5,term_months:6,location:'北京',storage_types:['文件']});now=2;const updated=c.saveEnterpriseLead({lead_id:lead.id,company:'补充公司'});assert.equal(updated.id,lead.id);assert.equal(updated.company,'补充公司');assert.equal(updated.location,'北京');assert.equal(updated.capacity_m3,3.5);assert.equal(updated.term_months,6);assert.deepEqual(updated.storage_types,['文件']);assert.equal(updated.created_at,1);assert.equal(updated.updated_at,2);assert.equal(c.state().enterpriseLeads.length,1);c.saveEnterpriseLead({lead_id:lead.id,company:'补充公司'});assert.equal(c.state().enterpriseLeads.length,1);assert.equal(c.authorized(),false);});
check('restored enterprise drafts can update the same ID after state hydration',()=>{const c=create(),lead=c.saveEnterpriseLead({phone:'13800000000',company:'原公司'});const restored=create({state:c.state()});restored.saveEnterpriseLead({lead_id:lead.id,company:'再次补充'});assert.equal(restored.state().enterpriseLeads.length,1);assert.equal(restored.state().enterpriseLeads[0].id,lead.id);assert.equal(restored.state().enterpriseLeads[0].company,'再次补充');});
check('invalid edits cannot partially overwrite a saved enterprise lead',()=>{const c=create(),lead=c.saveEnterpriseLead({phone:'13800000000',company:'原公司'});assert.throws(()=>c.saveEnterpriseLead({lead_id:lead.id,company:'不应保存',term_months:1.5}),/INVALID_TERM/);assert.deepEqual(c.state().enterpriseLeads,[lead]);assert.throws(()=>c.saveEnterpriseLead({lead_id:'missing',phone:'13800000000'}),/LEAD_NOT_FOUND/);assert.equal(c.state().enterpriseLeads.length,1);});
check('withdrawn leads cannot be revived by edit; explicit new request has a new ID',()=>{const c=create(),lead=c.saveEnterpriseLead({phone:'13800000000'});c.withdrawLead(lead.id);assert.throws(()=>c.saveEnterpriseLead({lead_id:lead.id,company:'已撤回'}),/LEAD_WITHDRAWN/);assert.equal(c.state().enterpriseLeads.length,1);const fresh=c.saveEnterpriseLead({phone:'13800000000',company:'明确新建'});assert.notEqual(fresh.id,lead.id);assert.equal(c.state().enterpriseLeads.length,2);assert.equal(c.state().enterpriseLeads[0].status,'withdrawn');assert.equal(c.state().leads.length,0);assert.equal(c.state().orders.length,0);});
check('enterprise supplementation preserves an existing exact item estimate',()=>{const c=create(),lead=c.saveEnterpriseLead({phone:'13800000000',capacity_m3:.576,term_months:6});const updated=c.saveEnterpriseLead({lead_id:lead.id,company:'补充资料'});assert.equal(updated.capacity_m3,.576);assert.equal(updated.term_months,6);assert.equal(updated.id,lead.id);assert.equal(c.state().enterpriseLeads.length,1);});
console.log(JSON.stringify({groups,result:'PASS'}));
